"""Private PNG storage. Paths and filenames are generated by the server."""

import hashlib
import struct
import uuid
import zlib
from datetime import timedelta
from pathlib import Path

from django.conf import settings
from django.db import transaction
from django.utils import timezone

from app.common.business import BusinessError

from .models import ExportBatch, ExportImage, WorkspaceSettings

MAX_PNG_BYTES = 16 * 1024 * 1024


def validate_png(data):
    if not data.startswith(b"\x89PNG\r\n\x1a\n") or len(data) > MAX_PNG_BYTES:
        raise BusinessError("请选择有效的清单 PNG 图片。")
    offset, header, ended, compressed = 8, None, False, bytearray()
    while offset + 12 <= len(data):
        size = struct.unpack(">I", data[offset : offset + 4])[0]
        kind = data[offset + 4 : offset + 8]
        payload = data[offset + 8 : offset + 8 + size]
        end = offset + 12 + size
        if (
            end > len(data)
            or zlib.crc32(kind + payload) != struct.unpack(">I", data[end - 4 : end])[0]
        ):
            raise BusinessError("PNG 图片不完整，请重新生成。")
        if header is None and kind != b"IHDR":
            raise BusinessError("PNG 缺少图片头。")
        if kind == b"IHDR":
            if header is not None or size != 13:
                raise BusinessError("PNG 图片头无效。")
            width, height, depth, color, compression, filtering, interlace = struct.unpack(
                ">IIBBBBB", payload
            )
            if (
                width != 920
                or not 1 <= height <= 16000
                or depth != 8
                or color not in (2, 6)
                or any((compression, filtering, interlace))
            ):
                raise BusinessError("图片尺寸或格式与清单不符，请重新生成。")
            header = (width, height, 4 if color == 6 else 3)
        elif kind == b"IDAT":
            compressed.extend(payload)
        elif kind == b"IEND":
            ended = size == 0 and end == len(data)
            break
        elif not (kind[0] & 32):
            raise BusinessError("PNG 包含不支持的图片数据。")
        offset = end
    if not header or not ended:
        raise BusinessError("PNG 图片不完整。")
    width, height, channels = header
    stride = width * channels + 1
    expected = stride * height
    try:
        decoder = zlib.decompressobj()
        pixels = decoder.decompress(bytes(compressed), expected + 1)
        if (
            len(pixels) != expected
            or not decoder.eof
            or decoder.unused_data
            or any(pixels[i] > 4 for i in range(0, expected, stride))
        ):
            raise ValueError()
    except (ValueError, zlib.error) as exc:
        raise BusinessError("PNG 图片数据无效，请重新生成。") from exc


def private_path(name):
    root = Path(settings.PRIVATE_MEDIA_ROOT).resolve()
    target = (root / name).resolve()
    if (
        not target.is_relative_to(root / "exports")
        or target != root / name
        or not name.startswith("exports/")
        or ".." in Path(name).parts
    ):
        raise BusinessError("清单文件位置无效。")
    return target


@transaction.atomic
def save_image(batch, page, data):
    if not 1 <= page <= max(1, len(batch.snapshot)):
        raise BusinessError("清单页码无效。")
    validate_png(data)
    batch = ExportBatch.objects.select_for_update().get(pk=batch.pk)
    old = ExportImage.objects.filter(batch=batch, page=page).first()
    if old and private_path(old.storage_name).is_file():
        return old
    digest = hashlib.sha256(data).hexdigest()
    name = f"exports/{batch.shop_id}/{batch.pk}/{uuid.uuid4().hex}.png"
    target = private_path(name)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(data)
    try:
        item, _ = ExportImage.objects.update_or_create(
            batch=batch,
            page=page,
            defaults={"storage_name": name, "sha256": digest},
        )
    except Exception:
        target.unlink(missing_ok=True)
        raise
    return item


def cleanup_images(*, dry_run=False):
    count = 0
    for config in WorkspaceSettings.objects.exclude(image_retention_days=None):
        if not config.image_retention_days:
            continue
        cutoff = timezone.now() - timedelta(days=config.image_retention_days)
        ids = ExportImage.objects.filter(
            batch__shop=config.shop, created_at__lt=cutoff
        ).values_list("pk", flat=True)
        for pk in list(ids):
            with transaction.atomic():
                item = (
                    ExportImage.objects.select_for_update()
                    .filter(pk=pk, created_at__lt=cutoff)
                    .first()
                )
                if item:
                    path = private_path(item.storage_name)
                    if not dry_run:
                        path.unlink(missing_ok=True)
                        item.delete()
                    count += 1
    return count
